import com.fixmer.genesis.technology.server.firstlaunch.*;
import java.nio.file.*;import java.security.*;import java.util.*;
/** Actual Ed25519/HMAC/filesystem tests. No Minecraft, native Job, or server migration claim. */
public final class RemoteControlChecks73 {
 static int checks;interface Work{void run()throws Exception;}static void check(boolean b){if(!b)throw new AssertionError("check "+checks);checks++;}static void refuse(Work w)throws Exception{try{w.run();throw new AssertionError("Unexpected authority");}catch(java.io.IOException|IllegalArgumentException|IllegalStateException expected){checks++;}}
 static final String INVENTORY="c".repeat(64);
 static byte[] packet(ControlRoom73 r,ControlRoom73.Member m,String action,String inv,UUID req)throws Exception{return LocalApply67.sign(m.secret,Map.of("schema","73","round",r.round.toString(),"client",m.id.toString(),"request",req.toString(),"action",action,"archive",r.offer.archiveSha(),"inventory",inv));}
 static void receipt(ControlRoom73 r,ControlRoom73.Member m,String action)throws Exception{r.receipt(packet(r,m,action,INVENTORY,UUID.randomUUID()));}
 static void keys(Path p,KeyPair kp)throws Exception{Files.createDirectories(p);Files.write(p.resolve("public.der"),kp.getPublic().getEncoded());Files.write(p.resolve("private.der"),kp.getPrivate().getEncoded());}
 static RemoteOffer69 offer(KeyPair kp){long n=System.currentTimeMillis();return new RemoteOffer69("localhost:25565","https://localhost/genesis/",UUID.randomUUID(),UUID.randomUUID(),null,"1.21.1","21.1.264",1,n,n+3600000,100,"a".repeat(64),FirstLaunchFiles.sha(kp.getPublic().getEncoded()));}
 static void unit(Path temp)throws Exception{
  var kp=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();Path id=temp.resolve("identity");keys(id,kp);var o=offer(kp);List<UUID> cohort=new ArrayList<>();for(int i=0;i<8;i++)cohort.add(UUID.randomUUID());
  var r=ControlRoom73.create(temp.resolve("control"),id,o,UUID.randomUUID(),UUID.randomUUID(),cohort);check(r.members().size()==8);refuse(r::commit);refuse(r::admit);refuse(()->ControlRoom73.create(r.root,id,o,r.instance,r.round,cohort));
  var first=r.member(cohort.get(0),false);refuse(()->receipt(r,first,"PREPARED"));for(UUID a:cohort)r.decision(a,"ACCEPTED");
  refuse(()->receipt(r,first,"INSTALLED"));refuse(()->receipt(r,first,"JOINED"));for(var m:r.members())receipt(r,m,"PREPARED");check(r.installed()==0&&r.denominator()==0);refuse(r::admit);
  byte[] prepared=packet(r,first,"PREPARED",INVENTORY,UUID.randomUUID());r.receipt(prepared);r.receipt(prepared);check(first.state.equals("PREPARED"));byte[] bad=prepared.clone();bad[bad.length/2]^=1;refuse(()->r.receipt(bad));
  var parsed=LocalApply67.verify(first.secret,prepared);refuse(()->r.receipt(packet(r,first,"ABORT",INVENTORY,UUID.fromString(parsed.get("request")))));
  Map<String,String> foreign=new HashMap<>(parsed);foreign.put("round",UUID.randomUUID().toString());refuse(()->r.receipt(LocalApply67.sign(first.secret,foreign)));foreign.put("round",r.round.toString());foreign.put("client",UUID.randomUUID().toString());refuse(()->r.receipt(LocalApply67.sign(first.secret,foreign)));foreign.put("client",first.id.toString());foreign.put("archive","f".repeat(64));refuse(()->r.receipt(LocalApply67.sign(first.secret,foreign)));
  var late=r.member(UUID.randomUUID(),false);r.decision(late.account,"ACCEPTED");receipt(r,late,"PREPARED");r.commit();check(r.denominator()==8&&r.needed()==2&&r.installed()==0&&!late.counted);refuse(r::cancel);refuse(r::commit);refuse(r::admit);refuse(()->r.receipt(packet(r,first,"PREPARED","d".repeat(64),UUID.randomUUID())));refuse(()->receipt(r,first,"ABORT"));
  receipt(r,late,"INSTALLED");check(r.installed()==0);receipt(r,first,"INSTALLED");check(r.installed()==1);refuse(r::admit);var second=r.member(cohort.get(1),false);receipt(r,second,"INSTALLED");check(r.installed()==2);r.admit();check(r.admission());receipt(r,first,"JOINED");receipt(r,first,"PREPARED");check(first.state.equals("JOINED")&&r.installed()==2);
  r.publish(System.currentTimeMillis());var state=ControlWire73.verify(kp.getPublic(),Files.readAllBytes(r.root.resolve("public/"+r.round+".state")));check(state.size()==16&&state.get("installed").equals("2")&&state.get("needed").equals("2")&&state.get("admission").equals("true"));String publicText=state.toString();for(var m:r.members()){check(!publicText.contains(HexFormat.of().formatHex(m.secret)));check(!publicText.contains(m.account.toString()));}
  var restored=ControlRoom73.restore(r.root,id);check(restored.denominator()==8&&restored.installed()==2&&restored.admission()&&restored.member(first.account,false).id.equals(first.id));check(restored.member(first.account,false).ack.equals(first.ack));refuse(()->ControlWire73.verify(KeyPairGenerator.getInstance("Ed25519").generateKeyPair().getPublic(),Files.readAllBytes(r.root.resolve("public/"+r.round+".state"))));
  // A committed journal survives original offer expiry; it must not silently revoke acted grants.
  long oldWall=System.currentTimeMillis();var expiredOffer=new RemoteOffer69(o.game(),o.endpoint(),o.distribution(),o.release(),o.parent(),o.minecraft(),o.neoforge(),o.sequence(),oldWall-120000,oldWall-1000,o.bytes(),o.archiveSha(),o.signer());Path journalPath=r.root.resolve(r.round+".journal");var journalData=new HashMap<>(ControlWire73.verify(kp.getPublic(),Files.readAllBytes(journalPath)));journalData.put("offer",Base64.getEncoder().encodeToString(expiredOffer.encode()));Files.write(journalPath,ControlWire73.sign(kp.getPrivate(),journalData));var expiredRestored=ControlRoom73.restore(r.root,id);check(expiredRestored.phase().equals("COMMITTED")&&expiredRestored.admission());expiredRestored.publish(System.currentTimeMillis());var freshState=ControlWire73.verify(kp.getPublic(),Files.readAllBytes(r.root.resolve("public/"+r.round+".state")));check(Long.parseLong(freshState.get("expires"))>System.currentTimeMillis());
  // Failed durable write cannot report installation in memory.
  var third=r.member(cohort.get(2),false);Path journal=r.root.resolve(r.round+".journal"),saved=r.root.resolve("saved");Files.move(journal,saved);Files.createDirectory(journal);refuse(()->receipt(r,third,"INSTALLED"));check(third.state.equals("PREPARED")&&r.installed()==2);Files.delete(journal);Files.move(saved,journal);
  r.closeRound();check(r.phase().equals("CLOSED")&&!Files.exists(r.root.resolve("active73")));refuse(()->receipt(r,third,"INSTALLED"));
  var cancelled=ControlRoom73.create(temp.resolve("cancel"),id,o,UUID.randomUUID(),UUID.randomUUID(),List.of(first.account));cancelled.decision(first.account,"ACCEPTED");cancelled.cancel();refuse(cancelled::commit);refuse(()->receipt(cancelled,cancelled.member(first.account,false),"PREPARED"));check(ControlRoom73.restore(cancelled.root,id).phase().equals("CANCELLED"));
  var aborted=ControlRoom73.create(temp.resolve("abort"),id,o,UUID.randomUUID(),UUID.randomUUID(),List.of(first.account,second.account));aborted.decision(first.account,"ACCEPTED");aborted.decision(second.account,"EXPIRED");receipt(aborted,aborted.member(first.account,false),"ABORT");refuse(aborted::commit);receipt(aborted,aborted.member(first.account,false),"PREPARED");aborted.commit();check(aborted.denominator()==1&&aborted.needed()==1);
  long wall=System.currentTimeMillis();var shortOffer=new RemoteOffer69(o.game(),o.endpoint(),o.distribution(),o.release(),o.parent(),o.minecraft(),o.neoforge(),o.sequence(),wall,wall+60000,o.bytes(),o.archiveSha(),o.signer());var shortRoom=ControlRoom73.create(temp.resolve("short"),id,shortOffer,UUID.randomUUID(),UUID.randomUUID(),List.of(first.account));shortRoom.decision(first.account,"ACCEPTED");receipt(shortRoom,shortRoom.member(first.account,false),"PREPARED");refuse(shortRoom::commit);check(shortRoom.phase().equals("PREPARING"));
  Path server=Files.createDirectories(temp.resolve("server"));Files.writeString(server.resolve("server.properties"),"online-mode=false\n");ControlSetup73.install(server,id);ControlSetup73.install(server,id);checks+=2;Path other=temp.resolve("other");keys(other,KeyPairGenerator.getInstance("Ed25519").generateKeyPair());refuse(()->ControlSetup73.install(server,other));
  byte[] signed=ControlWire73.sign(kp.getPrivate(),Map.of("a","Привет","b","value"));check(ControlWire73.verify(kp.getPublic(),signed).get("a").equals("Привет"));refuse(()->ControlWire73.decode("b=dg\na=dg\n".getBytes()));signed[signed.length-5]^=1;refuse(()->ControlWire73.verify(kp.getPublic(),signed));
  System.out.println("Remote73 real crypto/state/journal checks passed: "+checks);
 }
 public static void main(String[] args)throws Exception{
  if(args.length==0){Path p=Files.createTempDirectory("genesis73-checks-");try{unit(p);}finally{try(var files=Files.walk(p)){for(Path f:files.sorted(Comparator.reverseOrder()).toList())Files.delete(f);}}return;}
  Path root=Path.of(args[1]);if(args[0].equals("fixture")){var o=RemoteUpdateCli69.verifyPublic(root.resolve("public2"));UUID account=UUID.randomUUID();var r=ControlRoom73.create(root.resolve("control73"),root.resolve("identity"),o,UUID.randomUUID(),UUID.randomUUID(),List.of(account));r.decision(account,"ACCEPTED");r.publish(System.currentTimeMillis());FirstLaunchFiles.write(root.resolve("control73.cfg"),ControlWire73.encode(r.config(r.member(account,false),UUID.randomUUID())),false);return;}
  var r=ControlRoom73.restore(root.resolve("control73"),root.resolve("identity"));if(!args[0].equals("heartbeat"))r.drain();if(args[0].equals("commit"))r.commit();if(args[0].equals("admit"))r.admit();r.publish(System.currentTimeMillis());System.out.println(r.phase()+" "+r.installed()+" "+r.admission());
 }
}
